#!/usr/bin/env python3
"""Pebble virtual machine – a stack-based interpreter."""

import sys


def main():
    if len(sys.argv) < 2:
        print("Usage: vm.py PROGRAM.pbl", file=sys.stderr)
        sys.exit(1)

    program_text = open(sys.argv[1]).read()
    run(program_text)


def error(msg):
    """Print error and exit with code 1."""
    print(msg, file=sys.stdout)
    sys.exit(1)


def mask32(v):
    """Wrap value to 32-bit two's complement range."""
    v = v & 0xFFFFFFFF
    if v >= 0x80000000:
        v -= 0x100000000
    return v


def div_trunc(a, b):
    """Integer division truncated toward zero."""
    return int(a / b)


def mod_sign(a, b):
    """Remainder with sign following a (the dividend)."""
    r = a - (div_trunc(a, b) * b)
    return r


def run(program_text):
    lines = []
    for raw in program_text.splitlines():
        # Strip comments: everything from # onward
        line = raw.split('#')[0].strip()
        if line:
            lines.append(line)

    # Collect labels -> instruction index
    labels = {}
    for i, line in enumerate(lines):
        if line.endswith(':') and not line[:-1].strip():
            label_name = line[:-1].strip()
            labels[label_name] = i

    pc = 0
    stack = []
    variables = {}
    call_stack = []

    while pc < len(lines):
        line = lines[pc]
        parts = line.split(None, 1)
        opcode = parts[0]
        arg = parts[1] if len(parts) > 1 else None

        if opcode == 'HALT':
            break

        elif opcode == 'PUSH':
            stack.append(mask32(int(arg)))

        elif opcode == 'POP':
            if not stack:
                error('E01: stack is empty')
            stack.pop()

        elif opcode == 'DUP':
            if not stack:
                error('E01: stack is empty')
            stack.append(stack[-1])

        elif opcode == 'SWAP':
            if len(stack) < 2:
                error('E01: stack is empty')
            stack[-1], stack[-2] = stack[-2], stack[-1]

        elif opcode == 'ADD':
            if len(stack) < 2:
                error('E01: stack is empty')
            b = stack.pop()
            a = stack.pop()
            stack.append(mask32(a + b))

        elif opcode == 'SUB':
            if len(stack) < 2:
                error('E01: stack is empty')
            b = stack.pop()
            a = stack.pop()
            stack.append(mask32(a - b))

        elif opcode == 'MUL':
            if len(stack) < 2:
                error('E01: stack is empty')
            b = stack.pop()
            a = stack.pop()
            stack.append(mask32(a * b))

        elif opcode == 'DIV':
            if len(stack) < 2:
                error('E01: stack is empty')
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                error('E02: division by zero')
            stack.append(mask32(div_trunc(a, b)))

        elif opcode == 'MOD':
            if len(stack) < 2:
                error('E01: stack is empty')
            b = stack.pop()
            a = stack.pop()
            if b == 0:
                error('E02: division by zero')
            stack.append(mask32(mod_sign(a, b)))

        elif opcode == 'NEG':
            if not stack:
                error('E01: stack is empty')
            stack[-1] = mask32(-stack[-1])

        elif opcode == 'EQ':
            if len(stack) < 2:
                error('E01: stack is empty')
            b = stack.pop()
            a = stack.pop()
            stack.append(1 if a == b else 0)

        elif opcode == 'LT':
            if len(stack) < 2:
                error('E01: stack is empty')
            b = stack.pop()
            a = stack.pop()
            stack.append(1 if a < b else 0)

        elif opcode == 'GT':
            if len(stack) < 2:
                error('E01: stack is empty')
            b = stack.pop()
            a = stack.pop()
            stack.append(1 if a > b else 0)

        elif opcode == 'NOT':
            if not stack:
                error('E01: stack is empty')
            a = stack.pop()
            stack.append(1 if a == 0 else 0)

        elif opcode == 'LOAD':
            name = arg.strip()
            if name not in variables:
                error('E03: variable is not set')
            stack.append(variables[name])

        elif opcode == 'STORE':
            name = arg.strip()
            if not stack:
                error('E01: stack is empty')
            variables[name] = stack.pop()

        elif opcode == 'JMP':
            label = arg.strip()
            if label not in labels:
                error('E04: unknown label')
            pc = labels[label]
            continue

        elif opcode == 'JZ':
            if not stack:
                error('E01: stack is empty')
            val = stack.pop()
            label = arg.strip()
            if label not in labels:
                error('E04: unknown label')
            if val == 0:
                pc = labels[label]
                continue

        elif opcode == 'JNZ':
            if not stack:
                error('E01: stack is empty')
            val = stack.pop()
            label = arg.strip()
            if label not in labels:
                error('E04: unknown label')
            if val != 0:
                pc = labels[label]
                continue

        elif opcode == 'CALL':
            label = arg.strip()
            if label not in labels:
                error('E04: unknown label')
            call_stack.append(pc + 1)
            pc = labels[label]
            continue

        elif opcode == 'RET':
            if not call_stack:
                error('E05: no call frame')
            ret_pc = call_stack.pop()
            pc = ret_pc
            continue

        elif opcode == 'PRINT':
            if not stack:
                error('E01: stack is empty')
            print(stack.pop())

        else:
            error('E06: unknown instruction')

        pc += 1


if __name__ == '__main__':
    main()

